<?php require 'common.php'; if(($_GET['reauth']??'')==='1'){unset($_SESSION['admin_id']);session_regenerate_id(true);} if(!empty($_SESSION['admin_id'])){header('Location: dashboard.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$stmt=$db->prepare('SELECT * FROM admins WHERE username=?');$stmt->execute([trim((string)($_POST['username']??''))]);$admin=$stmt->fetch(PDO::FETCH_ASSOC);if($admin && password_verify((string)($_POST['password']??''),$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];header('Location: dashboard.php');exit;} $error='Incorrect username or password.';}layout_start('Administrator sign in', true); ?>
<div class="panel narrow login-panel"><p class="sub">Use your administrator account to continue.</p><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Sign in →</button></form></div><?php layout_end(); ?>
